{
  "technical_and_design_decisions": [
    "Target the existing Spring XD codebase (Java 8, Spring Framework 4.x / Spring Integration 4.1.x line) built with Gradle; all work is done on a feature branch of that codebase.",
    "U1: Implement the landing page in the XD Admin UI (Angular-based) as a new home view with higher-order navigation links routing to the existing Sources, Processors, Sinks, and Jobs sections; no new backend REST endpoints are required.",
    "U2: Implement configurable retry in the RabbitMessageBus by wiring a retry interceptor with a BinaryExceptionClassifier so the set of retryable exceptions is configurable via properties; support both bus-level default properties and per-stream deployment property overrides following the existing XD property resolution conventions.",
    "U2: Classify Kryo deserialization failures (KryoException/SerializationException) as non-retryable (fatal) by default, regardless of the configured retryable exception list.",
    "U3/U4/U5: Perform dependency version upgrades (Spring Integration 4.1.5, SI Kafka extension 1.2.0, Spring Hadoop 2.2.0 GA) via the build's dependency management, adapt code/configuration to any API changes, and validate through the existing regression test suites.",
    "U6: Expose module id and container id to deployed modules as module environment/context properties (e.g., via ModuleProperties) so component code can read them and include them in log output (e.g., via a logging MDC pattern).",
    "U7: Extend the KafkaMessageBus configuration to accept consumer properties (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer properties (batchSize, batchTimeout), with bus-level defaults overridable per stream via deployment properties.",
    "U8: Consolidate the XD and XD+Ambari RPM build/spec scripts into a single public Git repository organized by subdirectories (or build profiles) per variant, and validate both RPM builds from the merged repo.",
    "Testing strategy: unit tests per change plus integration tests against real RabbitMQ/Kafka/Hadoop test environments; a final cross-increment integration/system test pass is included."
  ],
  "assumptions": [
    "Estimates are effort (work-hours) for a single developer performing all design, coding, testing, and documentation; elapsed calendar duration is not estimated.",
    "The developer is familiar with the Spring XD codebase, and a working development environment plus CI infrastructure already exists.",
    "Integration test environments for RabbitMQ, Kafka, and Hadoop are available and do not require setup effort beyond normal use.",
    "U1 requires only front-end navigation work; the underlying section pages (sources, processors, sinks, jobs) already exist.",
    "For U3-U5, the upgraded library versions contain no major breaking API changes; minor code adaptations are included in the upgrade estimates.",
    "U2 scope includes defining the configuration properties, the retry classification logic, the default fatal classification for Kryo deserialization issues, and tests; the ClassNotFoundException/module classpath concern in the story is addressed by supporting the messaging MessageConversionException in the default configuration rather than changing module classloading.",
    "U8 covers repository restructuring, script consolidation, and build validation only; no functional changes to the RPM packaging logic are required.",
    "Code review, rework, documentation, and release notes are included as explicit activities.",
    "The specification lacks some details; reasonable assumptions were made instead of asking clarifying questions."
  ],
  "activities": [
    {
      "activity_id": "A-01",
      "activity_name": "Increment analysis and solution design",
      "activity_description": "Analyze the eight user stories, confirm scope, and produce the overall technical design (property model, retry classification approach, metadata exposure for module/container ids, repo consolidation plan).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-02",
      "activity_name": "U1: Landing page UI design",
      "activity_description": "Design the Admin UI landing page layout and navigation model with higher-order links to sources, processors, sinks, and jobs.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A-03",
      "activity_name": "U1: Landing page implementation",
      "activity_description": "Implement the landing page view, routing, and navigation links in the XD Admin UI.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-04",
      "activity_name": "U1: Landing page tests",
      "activity_description": "Write UI unit tests and end-to-end navigation checks for the landing page links.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-05",
      "activity_name": "U2: Rabbit retry configuration design",
      "activity_description": "Design the configurable retryable-exception mechanism for RabbitMessageBus, including bus-level and stream deployment property resolution and the default fatal classification for Kryo deserialization failures.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-06",
      "activity_name": "U2: Rabbit retry implementation",
      "activity_description": "Implement configurable exception classification (retry interceptor with BinaryExceptionClassifier), bus-level and deployment-level property handling, and non-retryable Kryo deserialization exceptions.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A-07",
      "activity_name": "U2: Rabbit retry tests",
      "activity_description": "Unit tests for classification/property resolution and integration tests against RabbitMQ verifying retry suppression and retryable-exception behavior.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A-08",
      "activity_name": "U3: Spring Integration 4.1.5 upgrade",
      "activity_description": "Bump the Spring Integration version to 4.1.5, resolve dependency conflicts, and adapt code/configuration to any API changes.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-09",
      "activity_name": "U3: Spring Integration upgrade regression tests",
      "activity_description": "Run and fix the regression test suite with focus on message channel behavior after the upgrade.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-10",
      "activity_name": "U4: SI Kafka extension 1.2.0 upgrade",
      "activity_description": "Upgrade the Spring Integration Kafka extension to 1.2.0, adapt configuration/code as needed, and run regression and performance smoke tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-11",
      "activity_name": "U5: Spring Hadoop 2.2.0 GA upgrade",
      "activity_description": "Upgrade Spring Hadoop to 2.2.0 GA, adapt configuration/code as needed, and run regression tests for Hadoop-related features.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A-12",
      "activity_name": "U6: Module id and container id exposure",
      "activity_description": "Design and implement injection of module id and container id into the module context/environment so components can include them in log output (including MDC-based logging support).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-13",
      "activity_name": "U6: Module metadata tests and docs",
      "activity_description": "Verify that modules can access module id and container id at runtime (e.g., via runtime modules scenarios) and document usage for module developers.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-14",
      "activity_name": "U7: Kafka bus property override implementation",
      "activity_description": "Design and implement consumer properties (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer properties (batchSize, batchTimeout) with bus-level defaults and per-stream deployment overrides in the KafkaMessageBus.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A-15",
      "activity_name": "U7: Kafka bus override tests and docs",
      "activity_description": "Unit and integration tests for consumer/producer property overrides against Kafka, plus property reference documentation.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-16",
      "activity_name": "U8: RPM scripts consolidation into single public repo",
      "activity_description": "Merge the XD and XD+Ambari RPM build/spec scripts into one public repository, restructure by variant, validate both RPM builds, and publish the repo.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "A-17",
      "activity_name": "Cross-increment integration and system testing",
      "activity_description": "End-to-end testing of the full increment (UI, Rabbit and Kafka buses, upgrades, module metadata) to catch interaction regressions.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-18",
      "activity_name": "Documentation and release notes",
      "activity_description": "Update reference documentation (retry configuration, Kafka bus properties, module/container id usage) and write release notes including the dependency upgrades and repo change.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-19",
      "activity_name": "Code review and rework",
      "activity_description": "Self-review, peer review cycles, and resulting rework across all changes in the increment.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 376
  }
}
